const KANJI=["","一","二","三","四","五","六","七","八","九","十","十一","十二","十三","十四","十五","十六","十七","十八","十九","二十","二十一","二十二","二十三","二十四","二十五","二十六","二十七","二十八","二十九","三十"];
function moonOf(k){
  const[y,m,d]=k.split("-").map(Number);
  const jd=Date.UTC(y,m-1,d,3,0,0)/86400000+2440587.5;
  const T=(jd-2451545)/36525,rad=Math.PI/180;
  const Ms=(357.5291092+35999.0502909*T)*rad;
  const Mm=(134.9633964+477198.8675055*T)*rad;
  const Dm=(297.8501921+445267.1114034*T)*rad;
  const Lm=218.3164477+481267.88123421*T
    +6.289*Math.sin(Mm)-1.274*Math.sin(Mm-2*Dm)+0.658*Math.sin(2*Dm)
    -0.214*Math.sin(2*Mm)-0.11*Math.sin(Dm);
  const Ls=280.46646+36000.76983*T+1.915*Math.sin(Ms)+0.02*Math.sin(2*Ms);
  let el=(Lm-Ls)%360;if(el<0)el+=360;
  const syn=29.530588853;
  const age=el/360*syn;
  const em=age<1.85?"\uD83C\uDF11":age<5.5?"\uD83C\uDF12":age<9.2?"\uD83C\uDF13":age<12.9?"\uD83C\uDF14":age<16.6?"\uD83C\uDF15":age<20.3?"\uD83C\uDF16":age<24?"\uD83C\uDF17":age<27.7?"\uD83C\uDF18":"\uD83C\uDF11";
  let holy=null;
  if(age<1||age>syn-0.5)holy="つきたち";else if(Math.abs(age-syn*0.25)<.6)holy="かたみに";
  else if(Math.abs(age-syn*0.5)<.6)holy="くまなし";else if(Math.abs(age-syn*0.75)<.6)holy="ありあけ";
  const rd=Math.floor(age)+1;
  return{age,emoji:em,holy,reki:(KANJI[rd]||rd)+"日"};
}
function tideOf(k){
  const[y,m,d]=k.split("-").map(Number);
  const n=Math.floor(Date.UTC(y,m-1,d)/86400000);
  const b=(n*50)%720;
  const f=x=>pad(Math.floor(x/60)%24)+":"+pad(x%60);
  return{port:"那覇",high:[f(b+372),f(b+1117)],low:[f(b+3),f(b+745)],demo:true};
}

