let AU=null;
function playSchumann(){
  if(AU){try{AU.ctx.close();}catch(e){}AU=null;render();return;}
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  const ctx=new AC();
  const carrier=ctx.createOscillator();carrier.type="sine";
  carrier.frequency.value=CONFIG.schumann.hz*CONFIG.schumann.mult;
  const gain=ctx.createGain();gain.gain.value=0;
  const lfo=ctx.createOscillator();lfo.type="sine";lfo.frequency.value=CONFIG.schumann.hz;
  const lfoGain=ctx.createGain();lfoGain.gain.value=0.12;
  lfo.connect(lfoGain);lfoGain.connect(gain.gain);
  carrier.connect(gain);gain.connect(ctx.destination);
  const t0=ctx.currentTime,dur=CONFIG.schumann.freeSec;
  gain.gain.setValueAtTime(0,t0);
  gain.gain.linearRampToValueAtTime(0.25,t0+1.2);
  gain.gain.setValueAtTime(0.25,t0+dur-2.5);
  gain.gain.linearRampToValueAtTime(0.0001,t0+dur);
  carrier.start(t0);lfo.start(t0);carrier.stop(t0+dur);lfo.stop(t0+dur);
  AU={ctx};
  carrier.onended=()=>{if(AU&&AU.ctx===ctx){try{ctx.close();}catch(e){}AU=null;render();}};
  render();
}
function elongAt(t){
  const jd=t/86400000+2440587.5;
  const T=(jd-2451545)/36525,rad=Math.PI/180;
  const Ms=(357.5291092+35999.0502909*T)*rad;
  const Mm=(134.9633964+477198.8675055*T)*rad;
  const Dm=(297.8501921+445267.1114034*T)*rad;
  const Lm=218.3164477+481267.88123421*T
    +6.289*Math.sin(Mm)-1.274*Math.sin(Mm-2*Dm)+0.658*Math.sin(2*Dm)
    -0.214*Math.sin(2*Mm)-0.11*Math.sin(Dm);
  const Ls=280.46646+36000.76983*T+1.915*Math.sin(Ms)+0.02*Math.sin(2*Ms);
  let el=(Lm-Ls)%360;if(el<0)el+=360;return el;
}
function nextMoons(n){
  const res=[],step=3600000,t=Date.now();let prev=elongAt(t);
  for(let i=1;i<24*70&&res.length<n;i++){
    const tt=t+i*step,e=elongAt(tt);
    if(prev>340&&e<20){let a=tt-step,b=tt;for(let j=0;j<24;j++){const m=(a+b)/2,d=(elongAt(m)-360+540)%360-180;if(d<0)a=m;else b=m;}res.push({type:"new",time:(a+b)/2});}
    if(prev<180&&e>=180){let a=tt-step,b=tt;for(let j=0;j<24;j++){const m=(a+b)/2,d=(elongAt(m)-180+540)%360-180;if(d<0)a=m;else b=m;}res.push({type:"full",time:(a+b)/2});}
    prev=e;
  }
  return res.sort((x,y)=>x.time-y.time).slice(0,n);
}
