function saveMemo(k,field,val){
  const day=S.memos[k]||{note:"",h:{}};
  if(field==="note")day.note=val;else{day.h=day.h||{};if(val)day.h[field]=val;else delete day.h[field];}
  if(!day.note&&Object.keys(day.h||{}).length===0)delete S.memos[k];else S.memos[k]=day;
  LS.set("onesea-memos",S.memos);
}

