/* ===== ナビ・描画 ===== */
function navHTML(){
  const items=[{id:"home",icon:"\u2302",label:"ホーム",color:"#C94D3A"}]
    .concat(SERVICES.map(s=>({id:s.id,icon:s.icon,label:s.short,color:s.color})));
  return `<div class="nav">${items.map(it=>{
    const on=S.view===it.id||(it.id==="home"&&S.view==="cal");
    const b=it.id!=="home"?S.badges[it.id]:0;
    return `<div data-go="${it.id}" class="${on?"on":""}"><div class="ni">${it.icon}
      ${b?`<div class="badge" style="top:-8px;right:-14px;transform:scale(.82)">${b}</div>`:""}</div>
      <div class="nl" style="${on?"color:"+it.color:""}">${it.label}</div></div>`;}).join("")}</div>`;
}
function render(){
  const app=$("app");
  if(!S.birth){app.style.paddingBottom="0";app.innerHTML=viewWelcome();bind();return;}
  app.style.paddingBottom="calc(72px + env(safe-area-inset-bottom))";
  if(S.view!=="home"&&S.view!=="cal"&&S.badges[S.view]){S.badges[S.view]=0;LS.set("onesea-badges",S.badges);}
  let v="";
  if(S.view==="home")v=viewHome();
  else if(S.view==="cal")v=viewCal();
  else if(S.view==="mmm")v=viewMMM();
  else if(S.view==="sekai")v=viewSekai();
  else if(S.view==="raku")v=viewRaku();
  else if(S.view==="tsuki")v=viewTsuki();
  app.innerHTML=v+sheetHTML()+navHTML();
  bind();
  if(S.editH!==null&&$("hin")){const el=$("hin");el.focus();el.setSelectionRange(el.value.length,el.value.length);}
}

/* ===== イベント ===== */
function bind(){
  const app=$("app");
  app.onclick=e=>{
    if(e.target.closest("a"))return;
    const t=e.target.closest("[data-go],[data-act],[data-mi],[data-day],[data-hour]");
    if(!t)return;
    if(t.dataset.go!==undefined){
      const svc=SERVICES.find(x=>x.id===t.dataset.go);
      if(svc&&svc.url&&svc.url!=="#"){
        if(S.badges[svc.id]){S.badges[svc.id]=0;LS.set("onesea-badges",S.badges);}
        window.open(svc.url,"_blank","noopener");render();return;
      }
      S.view=t.dataset.go;S.sheet=null;window.scrollTo(0,0);return render();}
    if(t.dataset.mi!==undefined){const n=+t.dataset.mi;if(n>=0&&n<=12){S.mi=n;S.sheet=null;render();}return;}
    if(t.dataset.day!==undefined){S.sheet=t.dataset.day;S.editH=null;render();return;}
    if(t.dataset.hour!==undefined){if(e.target.id==="hin")return;S.editH=+t.dataset.hour;return render();}
    const a=t.dataset.act;
    if(a==="start"){const v=$("binput").value;if(v){S.birth=v;LS.set("onesea-birth",v);S.view="home";render();}}
    else if(a==="closesheet"){S.sheet=null;S.expanded=false;render();}
    else if(a==="play"){playSchumann();}
    else if(a==="export"){
      const data={app:"onesea",version:1,birth:S.birth,ddp:S.ddp,memos:S.memos};
      const b=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});
      const u=URL.createObjectURL(b),el=document.createElement("a");
      el.href=u;el.download="onesea-data.json";el.click();URL.revokeObjectURL(u);
    }
    else if(a==="import"){const f=$("impfile");if(f)f.click();}
    else if(a==="member"){alert("会員のご案内はWebサイトで行います。\n（アプリ内には価格を表示しません — リーダーアプリ方式）");}
  };
  app.oninput=e=>{
    const el=e.target;
    if(el.id==="binput"){S.inputB=el.value;return;}
    if(el.id==="ddp"){S.ddp=el.value;LS.set("onesea-ddp",S.ddp);return;}
    if(el.id==="dnote"&&S.sheet){saveMemo(S.sheet,"note",el.value);return;}
    if(el.id==="hin"&&S.sheet&&S.editH!==null){saveMemo(S.sheet,S.editH,el.value);}
  };
  app.onkeydown=e=>{
    if(e.target.id==="hin"&&e.key==="Enter"){e.preventDefault();S.editH=S.editH<23?S.editH+1:null;render();}
  };
  const imp=$("impfile");
  if(imp)imp.onchange=e=>{
    const f=e.target.files[0];if(!f)return;
    const r=new FileReader();
    r.onload=()=>{try{
      const d=JSON.parse(r.result);
      if(d.app!=="onesea")throw 0;
      if(d.birth)S.birth=d.birth;
      if(typeof d.ddp==="string")S.ddp=d.ddp;
      if(d.memos&&typeof d.memos==="object")S.memos=d.memos;
      LS.set("onesea-birth",S.birth);LS.set("onesea-ddp",S.ddp);LS.set("onesea-memos",S.memos);
      e.target.value="";render();alert("読み込みました。おかえりなさい。");
    }catch(err){alert("読み込めませんでした。Onesea で書き出した JSON ファイルを選んでください。");}};
    r.readAsText(f);
  };
  const cb=$("calbody");
  if(cb)swipeX(cb,()=>{if(S.mi>0){S.mi--;S.sheet=null;render();}},()=>{if(S.mi<12){S.mi++;S.sheet=null;render();}});
  const sb=$("sheetbody");
  if(sb)swipeX(sb,()=>shiftDay(-1),()=>shiftDay(1),true);
  const hd=$("handle");
  if(hd)dragSheet(hd);
}
function shiftDay(off){
  const[y,m,d]=S.sheet.split("-").map(Number);
  const nd=new Date(y,m-1,d+off);
  S.sheet=keyOf(nd.getFullYear(),nd.getMonth()+1,nd.getDate());
  S.editH=null;render();
  const sb=$("sheetbody");if(sb)sb.scrollTop=0;
}
function swipeX(el,onRight,onLeft,inner){
  let sx=0,sy=0,dir=null,dx=0,active=false;
  const target=inner?el.firstElementChild||el:el;
  el.addEventListener("touchstart",e=>{const t=e.touches[0];sx=t.clientX;sy=t.clientY;dir=null;dx=0;active=true;
    target.style.transition="none";},{passive:true});
  el.addEventListener("touchmove",e=>{
    if(!active)return;
    const t=e.touches[0];const ax=t.clientX-sx,ay=t.clientY-sy;
    if(!dir){if(Math.abs(ax)>10||Math.abs(ay)>10)dir=Math.abs(ax)>Math.abs(ay)*1.3?"x":"y";return;}
    if(dir!=="x")return;
    e.preventDefault();
    const max=window.innerWidth*.55,r=Math.min(Math.abs(ax)/window.innerWidth,1);
    dx=(ax>0?1:-1)*max*Math.pow(r,.72);
    target.style.transform="translateX("+dx+"px)";
  },{passive:false});
  el.addEventListener("touchend",()=>{
    if(!active)return;active=false;
    target.style.transition="transform .22s cubic-bezier(.22,1,.36,1)";
    const th=window.innerWidth*.18;
    if(dx>th){target.style.transform="translateX(100vw)";setTimeout(onRight,180);}
    else if(dx<-th){target.style.transform="translateX(-100vw)";setTimeout(onLeft,180);}
    else target.style.transform="";
    dx=0;dir=null;
  },{passive:true});
}
function dragSheet(handle){
  const sheet=$("sheet");let sy=0,cur=0,drag=false;
  handle.addEventListener("touchstart",e=>{sy=e.touches[0].clientY;drag=true;cur=0;sheet.style.transition="none";},{passive:true});
  handle.addEventListener("touchmove",e=>{if(!drag)return;e.preventDefault();
    cur=e.touches[0].clientY-sy;sheet.style.transform="translateY("+Math.max(-140,cur)+"px)";},{passive:false});
  handle.addEventListener("touchend",()=>{
    if(!drag)return;drag=false;
    sheet.style.transition="transform .28s cubic-bezier(.22,1,.36,1)";sheet.style.transform="";
    if(cur<-60){S.expanded=true;render();}
    else if(cur>90){S.sheet=null;S.expanded=false;render();}
    else if(cur>40&&S.expanded){S.expanded=false;render();}
  },{passive:true});
  handle.addEventListener("click",()=>{S.expanded=!S.expanded;render();});
}

/* ===== 起動 ===== */
render();
if("serviceWorker" in navigator){
  window.addEventListener("load",()=>navigator.serviceWorker.register("sw.js").catch(()=>{}));
}

